    fn get_event_name(event: Self::Event) -> &'static str {
        match event {
            StaticStateAlgorithmEnumEvent::Check => "check",
            StaticStateAlgorithmEnumEvent::Count => "count",
            StaticStateAlgorithmEnumEvent::ErrorExecution => "error.execution",
            StaticStateAlgorithmEnumEvent::ItemAdded => "item.added",
            StaticStateAlgorithmEnumEvent::ItemMoved => "item.moved",
            StaticStateAlgorithmEnumEvent::Null => "",
        }
    }

    fn get_event_from_name(name: &str) -> Option<Self::Event> {
        match name {
            "check" => Some(StaticStateAlgorithmEnumEvent::Check),
            "count" => Some(StaticStateAlgorithmEnumEvent::Count),
            "error.execution" => Some(StaticStateAlgorithmEnumEvent::ErrorExecution),
            "item.added" => Some(StaticStateAlgorithmEnumEvent::ItemAdded),
            "item.moved" => Some(StaticStateAlgorithmEnumEvent::ItemMoved),
            _ => None,
        }
    }

    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            StaticStateAlgorithmEnumState::Board => "board",
        }
    }

    // The inverse of the table above, emitted from the same loop over the
    // document's states so the two age together. It is what lets a host turn a
    // recorded configuration back into the slice `enter_at` takes.
    fn get_state_from_name(name: &str) -> Option<Self::State> {
        match name {
            "board" => Some(StaticStateAlgorithmEnumState::Board),
            _ => None,
        }
    }

    fn null_event() -> Self::Event {
        StaticStateAlgorithmEnumEvent::Null
    }

    // NL→IR Item C1 Path A: store the current event's typed `_event.data`
    // payload so native transition guards can read it without a script
    // engine. Called by the engine's pop loop for every dequeued event;
    // events injected without a typed payload carry the `#[default] None`
    // variant, against which the variant-specific guards simply fail.
    fn populate_event_payload(&mut self, payload: &Self::Payload) {
        self.pending_payload = payload.clone();
    }

    // NL→IR Item C1 Path A: …and when no typed payload rode with the event,
    // read that view out of the `data` every other producer fills — `<send>`
    // with `<param>`, an invoke forwarding either way, autoforward, BasicHTTP,
    // mesh. A payload that does not read as this event's schema is returned as
    // a refusal, which the engine raises as `error.execution`.
    fn lift_event_payload(
        &mut self,
        event: Self::Event,
        data: &str,
    ) -> ::core::result::Result<(), ::sce_rust_runtime::event_payload::PayloadRefusal> {
        // A typed payload already bound the view, so the producer was the inject
        // seam and there is nothing to read out of `data`.
        if self.pending_payload != StaticStateAlgorithmEnumPayload::None {
            return Ok(());
        }
        match event {
            StaticStateAlgorithmEnumEvent::ItemAdded => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = StaticStateAlgorithmEnumPayload::ItemAdded(
                    StaticStateAlgorithmEnumItemAddedPayload {
                        id: fields.unsigned::<u32>("id")?,
                        status: match fields.text("status")?.as_str() {
                            "open" => StaticStateAlgorithmEnumStatusEnum::Open,
                            "in_progress" => StaticStateAlgorithmEnumStatusEnum::InProgress,
                            "done" => StaticStateAlgorithmEnumStatusEnum::Done,
                            other => {
                                return Err(::sce_rust_runtime::event_payload::PayloadRefusal::new(
                                    format!("status ({other}) is not a variant of Status"),
                                ))
                            }
                        },
                    },
                );
            }
            StaticStateAlgorithmEnumEvent::ItemMoved => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = StaticStateAlgorithmEnumPayload::ItemMoved(
                    StaticStateAlgorithmEnumItemMovedPayload {
                        id: fields.unsigned::<u32>("id")?,
                        status: match fields.text("status")?.as_str() {
                            "open" => StaticStateAlgorithmEnumStatusEnum::Open,
                            "in_progress" => StaticStateAlgorithmEnumStatusEnum::InProgress,
                            "done" => StaticStateAlgorithmEnumStatusEnum::Done,
                            other => {
                                return Err(::sce_rust_runtime::event_payload::PayloadRefusal::new(
                                    format!("status ({other}) is not a variant of Status"),
                                ))
                            }
                        },
                    },
                );
            }
            _ => {}
        }
        Ok(())
    }

