                    let sce_failed =
                        match (|| -> Result<(), sce_forge_runtime::algorithm::AlgorithmError> {
                            self.items = sce_forge_runtime::algorithm::within(
                                (call_SetStatus__v(&self.items, ev.id, ev.status)?).as_slice(),
                                4,
                            )?
                            .to_vec();
                            Ok(())
                        })() {
                            Ok(()) => false,
                            Err(_) => {
                                engine.raise(sce_rust_runtime::EventWithMetadata::platform_error(StaticStateAlgorithmEnumEvent::ErrorExecution, "<assign location='items'>: an integer operation overflowed or failed"));
                                true
                            }
                        };
                    if sce_failed {
                        break 'action_block; // W3C SCXML 4.9: the error ends the block
                    }

                    // W3C SCXML 5.3: <assign location="last">
                    self.last = call_StatusOf__v(&self.items, ev.id);
